export interface Product {
  sku: string;
  unitCents: number;
  promotionEligible: boolean;
}
export interface CartLine {
  sku: string;
  quantity: number;
}
export interface Promotion {
  code: string;
  percent: number;
  minimumEligibleCents: number;
  maximumDiscountCents?: number;
}
export interface PricedLine extends CartLine {
  unitCents: number;
  subtotalCents: number;
}
export interface CartQuote {
  lines: PricedLine[];
  subtotalCents: number;
  discountCents: number;
  totalCents: number;
  appliedCode: string | null;
}
import { Catalog } from './catalog.js';
import type { CartLine, CartQuote, PricedLine } from './model.js';
import { addCents, promotionDiscount, validateLine } from './policy.js';

export interface QuoteRequest {
  lines: readonly CartLine[];
  promotionCode?: string;
}

export class CartPricing {
  constructor(private readonly catalog: Catalog) {}

  quote(request: QuoteRequest): CartQuote {
    const lines: PricedLine[] = [];
    let subtotalCents = 0;
    for (const line of request.lines) {
      validateLine(line);
      const product = this.catalog.product(line.sku);
      const lineCents = addCents(0, product.unitCents * line.quantity);
      subtotalCents = addCents(subtotalCents, lineCents);
      lines.push({
        sku: line.sku,
        quantity: line.quantity,
        unitCents: product.unitCents,
        subtotalCents: lineCents,
      });
    }
    const promotion = request.promotionCode === undefined
      ? undefined : this.catalog.promotion(request.promotionCode);
    let discountCents = 0;
    let appliedCode: string | null = null;
    if (promotion && subtotalCents >= promotion.minimumEligibleCents) {
      discountCents = promotionDiscount(subtotalCents, promotion);
      if (discountCents > 0) appliedCode = promotion.code;
    }
    return {
      lines,
      subtotalCents,
      discountCents,
      totalCents: subtotalCents - discountCents,
      appliedCode,
    };
  }
}
import type { CartLine, Product, Promotion } from './model.js';

export function validateLine(line: CartLine): void {
  if (!line.sku || !Number.isSafeInteger(line.quantity) || line.quantity < 1) {
    throw new RangeError('Invalid cart line');
  }
}

export function validateProduct(product: Product): void {
  if (!Number.isSafeInteger(product.unitCents) || product.unitCents < 0) {
    throw new RangeError('Invalid product price');
  }
}

export function validatePromotion(promotion: Promotion): void {
  if (!promotion.code || !Number.isInteger(promotion.percent)
    || promotion.percent < 1 || promotion.percent > 100
    || !Number.isSafeInteger(promotion.minimumEligibleCents)
    || promotion.minimumEligibleCents < 0
    || (promotion.maximumDiscountCents !== undefined
      && (!Number.isSafeInteger(promotion.maximumDiscountCents)
        || promotion.maximumDiscountCents < 0))) {
    throw new RangeError('Invalid promotion');
  }
}

export function addCents(a: number, b: number): number {
  const total = a + b;
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('Cart amount exceeds supported range');
  }
  return total;
}

// Discounts round down once for the supplied base, then apply the cap.
export function promotionDiscount(baseCents: number, promotion: Promotion): number {
  const rounded = Number(BigInt(baseCents) * BigInt(promotion.percent) / 100n);
  return Math.min(rounded, promotion.maximumDiscountCents ?? rounded);
}
import type { Product, Promotion } from './model.js';
import { validateProduct, validatePromotion } from './policy.js';

export class Catalog {
  private readonly products = new Map<string, Product>();
  private readonly promotions = new Map<string, Promotion>();

  constructor(products: readonly Product[], promotions: readonly Promotion[]) {
    for (const product of products) {
      validateProduct(product);
      this.products.set(product.sku, { ...product });
    }
    for (const promotion of promotions) {
      validatePromotion(promotion);
      this.promotions.set(promotion.code, { ...promotion });
    }
  }

  product(sku: string): Product {
    const product = this.products.get(sku);
    if (!product) throw new Error(`Unknown SKU: ${sku}`);
    return { ...product };
  }

  promotion(code: string): Promotion | undefined {
    const promotion = this.promotions.get(code);
    return promotion ? { ...promotion } : undefined;
  }
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { Catalog } from '../dist/catalog.js';
import { CartPricing } from '../dist/cart.js';
const make = () => new CartPricing(new Catalog([
  {sku:'book',unitCents:199,promotionEligible:true},
], [{code:'SAVE',percent:10,minimumEligibleCents:300}]));
test('quantities, repeated lines, rounding and original order', () => {
  const result = make().quote({lines:[{sku:'book',quantity:1},{sku:'book',quantity:2}],promotionCode:'SAVE'});
  assert.equal(result.subtotalCents,597);
  assert.equal(result.discountCents,59);
  assert.equal(result.totalCents,538);
  assert.deepEqual(result.lines.map(x => x.quantity),[1,2]);
});
test('unknown codes remain no discount and invalid lines throw', () => {
  assert.equal(make().quote({lines:[],promotionCode:'missing'}).appliedCode,null);
  assert.throws(() => make().quote({lines:[{sku:'book',quantity:0}]}),RangeError);
  assert.throws(() => make().quote({lines:[{sku:'missing',quantity:1}]}),/Unknown SKU/);
});

